    assert.match(detail, /aria-label="Complete Renamed" checked/);
    assert.ok(detail.indexOf('Complete Renamed') < detail.indexOf('Complete Pending'));
    assert.doesNotMatch(await get('/projects/1?filter=Open'), /Complete Renamed/);
