    selected(detail, 1, 'High', true);
    selected(detail, 2, 'Low', true);
    assert.equal((await post('/projects/1/tasks/1/priority', { priority: 'Low' })).status, 403);
    assert.equal(await get('/projects/1'), detail);
    await server.stop();
    server = await launch(dbPath);
    assert.equal(await get('/projects/1'), detail);
